"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[1638],{62620:e=>{e.exports=JSON.parse('{"tag":{"label":"Self-Supervised Learning","permalink":"/science/tags/self-supervised-learning","allTagsPath":"/science/tags","count":3,"items":[{"id":"2025/autonomous-camera-control","title":"An Autonomous Camera Control System Inspired by Curiosity","description":"Author: Yufeng Luo, MCS Research Aide, University of Wyoming, Summer 2024","permalink":"/science/2025/autonomous-camera-control"},{"id":"2024/sound-separation","title":"Sound Separation","description":"By processing data directly at the collection source, edge computing networks like Sage/Waggle offer unique advantages over using centralized servers for ecological monitoring tasks. Audio in particular is useful for tracking metrics like noise pollution from human development or population statistics for vocal wildlife in the area (birds, insects, frogs, etc.). Further analysis can provide deeper insights into the overall health of the ecosystems where nodes are deployed.","permalink":"/science/2024/sound-separation"},{"id":"2023/collaboration","title":"Unleashing the Power of Collaboration","description":"Clouds have long fascinated humans because of their complex and diverse nature. To gain a deeper understanding of these atmospheric phenomena, a multidisciplinary team of computer scientists, meteorologists, and machine learning experts from Northwestern-Argonne Institute of Science and Engineering (NAISE) collaborated on the National Science Foundation (NSF)-supported Sage project. The project\'s goal was to develop new edge computing technologies that would allow scientists to collect and analyze large amounts of data from advanced sensors in real time.","permalink":"/science/2023/collaboration"}],"unlisted":false}}')}}]);